243	      logger.info('No members found in database');
244	      res.json({ success: true, message: 'No members to sync', synced: 0, failed: 0 });
245	      return;
246	    }
247	
248	    const results = {
249	      synced: 0,
250	      failed: 0,
251	      errors: [] as { discord_uid: string; error: string }[],
252	    };
253	
254	    // 各メンバーのロールを同期
255	    for (const memberData of members as Member[]) {
