329	            logger.info(`Added leader role to ${memberData.discord_uid}`);
330	          } else if (!isLeader && hasLeaderRole) {
331	            await removeRoleFromMember(member, leaderRoleId);
332	            rolesRemoved.push(leaderRoleId);
333	            logger.info(`Removed leader role from ${memberData.discord_uid}`);
334	          }
335	        }
